import AppKit

/// An action runnable from the command palette. Menu items and palette share these.
@MainActor
struct PaletteCommand: Identifiable {
    let id: String
    let title: String
    let icon: String
    /// The default shortcut ("cmd+shift+b"); Keybindings has the one in effect.
    let key: String?
    let isAvailable: (Workspace) -> Bool
    let perform: (Workspace) -> Void

    private static func supports(_ workspace: Workspace, _ feature: LanguageClient.Feature) -> Bool {
        workspace.activeDocument?.languageClient?.supports(feature) == true
    }

    static let all: [PaletteCommand] = [
        PaletteCommand(id: "go.quickOpen", title: "Go to File…", icon: "doc.text.magnifyingglass", key: "cmd+p",
                       isAvailable: { $0.rootNode != nil }, perform: { $0.showPalette(.files) }),
        PaletteCommand(id: "go.workspaceSymbol", title: "Go to Symbol in Workspace…", icon: "number", key: "cmd+t",
                       isAvailable: { $0.rootURL != nil }, perform: { $0.showPalette(.workspaceSymbols) }),
        PaletteCommand(id: "go.symbol", title: "Go to Symbol in File…", icon: "at", key: "shift+cmd+o",
                       isAvailable: { $0.activeDocument != nil }, perform: { $0.showPalette(.symbols) }),
        PaletteCommand(id: "view.outline", title: "View: Show Outline", icon: "list.bullet.indent", key: nil,
                       isAvailable: { _ in true }, perform: { $0.sidebarMode = .outline }),
        PaletteCommand(id: "view.toggleCodeLens", title: "View: Toggle Code Lens", icon: "eyeglasses", key: nil,
                       isAvailable: { _ in true }, perform: { _ in AppSettings.shared.showsCodeLens.toggle() }),
        PaletteCommand(id: "view.toggleInlayHints", title: "View: Toggle Inlay Hints", icon: "text.insert", key: nil,
                       isAvailable: { _ in true }, perform: { _ in AppSettings.shared.showsInlayHints.toggle() }),
        PaletteCommand(id: "view.toggleBreadcrumbs", title: "View: Toggle Breadcrumbs", icon: "chevron.right.2", key: nil,
                       isAvailable: { _ in true }, perform: { _ in AppSettings.shared.showsBreadcrumbs.toggle() }),
        PaletteCommand(id: "go.line", title: "Go to Line…", icon: "arrow.right.to.line", key: "ctrl+g",
                       isAvailable: { $0.activeDocument != nil }, perform: { $0.showPalette(.goToLine) }),
        PaletteCommand(id: "go.definition", title: "Go to Definition", icon: "arrow.turn.down.right", key: "f12",
                       isAvailable: { $0.activeDocument?.languageClient != nil }, perform: { $0.goToDefinition() }),
        PaletteCommand(id: "go.implementation", title: "Go to Implementation", icon: "arrow.down.right.square", key: "cmd+f12",
                       isAvailable: { supports($0, .implementation) }, perform: { $0.goToImplementation() }),
        PaletteCommand(id: "go.typeDefinition", title: "Go to Type Definition", icon: "t.square", key: nil,
                       isAvailable: { supports($0, .typeDefinition) }, perform: { $0.goToTypeDefinition() }),
        PaletteCommand(id: "go.callHierarchy", title: "Show Call Hierarchy", icon: "phone.arrow.down.left", key: "alt+shift+h",
                       isAvailable: { supports($0, .callHierarchy) }, perform: { $0.showCallHierarchy() }),
        PaletteCommand(id: "go.outgoingCalls", title: "Show Outgoing Calls", icon: "phone.arrow.up.right", key: nil,
                       isAvailable: { supports($0, .callHierarchy) }, perform: { $0.showCallHierarchy(incoming: false) }),
        PaletteCommand(id: "edit.codeActions", title: "Quick Fix & Refactor…", icon: "lightbulb", key: "cmd+.",
